export const soundWorkshopCss=`:root{color-scheme:dark;--bg:#0b121b;--panel:#152631;--line:#3f5d6e;--text:#edf4f5;--accent:#edbf89}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:18px/1.5 system-ui,sans-serif}h1{font-size:27px;margin:0}h2{font-size:22px;color:var(--accent);margin:12px 0}button,input,select,textarea{font:inherit;color:inherit}button,input,select,textarea{background:#203a47;border:1px solid var(--line);border-radius:9px;padding:10px;max-width:100%}button{cursor:pointer;min-height:44px}button:hover{background:#355565}button:disabled{opacity:.5;cursor:default}button[aria-pressed=true],.sw-primary{outline:2px solid var(--accent)}:focus-visible{outline:3px solid #6ddbe2;outline-offset:2px}input:not([type=checkbox]),select,textarea{width:100%}input[type=checkbox]{width:20px;height:20px}label{display:block;margin:10px 0;font-size:17px}p{margin:8px 0}.sw-header{padding:14px 22px;border-bottom:1px solid var(--line)}.sw-grid{display:grid;grid-template-columns:minmax(0,1fr) 400px;grid-template-rows:minmax(0,1fr);gap:16px;padding:16px;height:calc(100dvh - 150px);min-height:0}.sw-library,.sw-side{min-height:0;overflow:auto;padding:16px;background:var(--panel);border:1px solid var(--line);border-radius:14px}.sw-topics{display:grid;grid-template-columns:1fr 2fr;gap:12px}.sw-theme-tools{padding:10px 0;margin-bottom:12px;border-bottom:1px solid var(--line)}.sw-theme-tools input{max-width:420px}.sw-filters{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px}.sw-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,280px),1fr));gap:12px}.sw-card{padding:16px;border:1px solid var(--line);border-radius:12px;overflow-wrap:anywhere}.sw-card h3{font-size:20px;margin:0 0 6px}.sw-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.sw-help{font-size:15px;color:#bfced6;line-height:1.6}.sw-badge{font-size:14px;color:#f2cc9e}.sw-status{padding:8px 22px;min-height:44px;overflow-wrap:anywhere}.sw-error{white-space:pre-wrap;color:#ffc6ad;font-size:15px;max-height:120px;overflow:auto}.sw-player{width:100%;margin:8px 0}.sw-selected{overflow-wrap:anywhere;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:16px}.sw-transcript{max-height:220px;overflow:auto;font-size:17px;white-space:pre-wrap}.sw-mix-item{padding:12px;margin:12px 0;border:1px solid var(--line);border-radius:10px}.sw-numbers{display:grid;grid-template-columns:1fr 1fr;gap:8px}.sw-numbers label{min-width:0}.sw-link{color:#f2cc9e}.sw-progress{width:100%}summary{cursor:pointer;color:var(--accent)}.sw-drop{outline:3px dashed #6ddbe2}.sw-side button{font-size:16px}@media(max-width:1100px){.sw-grid{grid-template-columns:minmax(0,1fr) 350px}.sw-filters{grid-template-columns:1fr 1fr}}@media(max-width:800px){.sw-grid{height:auto;grid-template-columns:1fr}.sw-library,.sw-side{max-height:85dvh}.sw-side{grid-row:1}.sw-filters,.sw-topics{grid-template-columns:1fr 1fr}}`;

